fn dims() -> i32 {
    (480 << 16) | 270
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let hz: i32 = h * 3 / 5;
    let mut y: i32 = 0;
    while y < hz {
        let r: i32 = 26 + (255 - 26) * y / hz;
        let g: i32 = 5 + (144 - 5) * y / hz;
        let b: i32 = 51 + (64 - 51) * y / hz;
        host::display::fill_rect(0, y, w, 1, r * 65536 + g * 256 + b);
        y = y + 1;
    }
    let scy: i32 = hz - 34;
    let mut dy: i32 = 0 - 30;
    while dy <= 30 {
        if scy + dy < hz {
            let mut hw: i32 = 30;
            while hw * hw + dy * dy > 900 {
                hw = hw - 1;
            }
            host::display::fill_rect(w / 2 - hw, scy + dy, hw * 2 + 1, 1, 0xffe9a0);
        }
        dy = dy + 1;
    }
    host::display::fill_rect(0, hz, w, h - hz, 0x0a1030);
    let mut sy: i32 = hz + 3;
    while sy < h {
        let mut hsh: i32 = sy * 7919 + (t / 6) * 104729;
        hsh = hsh * 1103515245 + 12345;
        let sx: i32 = ((hsh >> 16) & 32767) % (w - 60);
        host::display::fill_rect(sx, sy, 60, 1, 0x35507a);
        hsh = hsh * 1103515245 + 12345;
        let gx: i32 = w / 2 - 20 + ((hsh >> 16) & 31);
        host::display::fill_rect(gx, sy, 22, 1, 0xd8a060);
        sy = sy + 6;
    }
    host::display::present();
}
